import{_ as e,o as s,c as t,a8 as i}from"./chunks/framework.DQoZbSQ3.js";const o="/docs/assets/codex-desktop-01.Cy5EExPX.jpg",n="/docs/assets/codex-desktop-02.DCT0Yw0W.jpg",d="/docs/assets/codex-desktop-03.Bfbcq6hy.jpg",l="/docs/assets/codex-desktop-04.BHXSFhmN.jpg",r="/docs/assets/codex-desktop-05.CTmsXlVo.jpg",p="/docs/assets/codex-desktop-06.DAAheLZq.jpg",E=JSON.parse('{"title":"Codex 桌面版接入熊猫算力 · 完整教程","description":"","frontmatter":{"title":"Codex 桌面版接入熊猫算力 · 完整教程","date":"2026-05-19T00:00:00.000Z","category":"拓展连接","tags":["Codex","桌面版","接入教程","开发者"]},"headers":[],"relativePath":"connect/codex-desktop.md","filePath":"connect/codex-desktop.md","lastUpdated":1779265215000}'),c={name:"connect/codex-desktop.md"};function h(k,a,u,b,m,x){return s(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="codex-桌面版接入熊猫算力-·-完整教程" tabindex="-1">Codex 桌面版接入熊猫算力 · 完整教程 <a class="header-anchor" href="#codex-桌面版接入熊猫算力-·-完整教程" aria-label="Permalink to &quot;Codex 桌面版接入熊猫算力 · 完整教程&quot;">​</a></h1><p>Codex 桌面版没有图形化的 API 配置入口，需要手动改 <code>auth.json</code> 和 <code>config.toml</code>。只要把两个文件配对好，就能通过熊猫算力的 OpenAI 兼容网关直连 GPT。</p><p><strong>预计用时：10 分钟 · 推荐人群：开发者 · 支持平台：Windows / macOS</strong></p><hr><h2 id="什么是-codex-桌面版" tabindex="-1">什么是 Codex 桌面版？ <a class="header-anchor" href="#什么是-codex-桌面版" aria-label="Permalink to &quot;什么是 Codex 桌面版？&quot;">​</a></h2><p>Codex 桌面版是 OpenAI 的桌面编程助手，可以读项目、改文件、跑命令。接入熊猫算力后，不需要登录 OpenAI 账号，也能直接使用中转的模型接口。</p><div class="tip custom-block"><p class="custom-block-title">提前说明</p><p>本教程以 Windows 为主，macOS 只是在路径上不同，配置逻辑是一样的。</p></div><hr><h2 id="step-01-准备安装包" tabindex="-1">Step 01：准备安装包 <a class="header-anchor" href="#step-01-准备安装包" aria-label="Permalink to &quot;Step 01：准备安装包&quot;">​</a></h2><h3 id="_1-下载-codex-桌面客户端" tabindex="-1">1. 下载 Codex 桌面客户端 <a class="header-anchor" href="#_1-下载-codex-桌面客户端" aria-label="Permalink to &quot;1. 下载 Codex 桌面客户端&quot;">​</a></h3><p>前往 OpenAI 官方下载页，获取对应系统的安装包。Windows 一般是 <code>Codex Installer.exe</code>，macOS 是 <code>.dmg</code> 文件。</p><p><img src="'+o+'" alt="Codex Installer.exe 下载弹窗"></p><h3 id="_2-安装后先不要登录" tabindex="-1">2. 安装后先不要登录 <a class="header-anchor" href="#_2-安装后先不要登录" aria-label="Permalink to &quot;2. 安装后先不要登录&quot;">​</a></h3><p>安装完成后直接退出客户端，不要先登录任何账号。Codex 之后是否走中转，主要取决于本地配置文件。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>第一次启动时如果遇到系统拦截，先放行安装，不要急着登录。</p></div><hr><h2 id="step-02-获取熊猫算力-api-key" tabindex="-1">Step 02：获取熊猫算力 API Key <a class="header-anchor" href="#step-02-获取熊猫算力-api-key" aria-label="Permalink to &quot;Step 02：获取熊猫算力 API Key&quot;">​</a></h2><h3 id="_1-登录熊猫算力后台" tabindex="-1">1. 登录熊猫算力后台 <a class="header-anchor" href="#_1-登录熊猫算力后台" aria-label="Permalink to &quot;1. 登录熊猫算力后台&quot;">​</a></h3><p>进入控制台的令牌管理页面，新建一个以 <code>sk-</code> 开头的 API Key。</p><h3 id="_2-记住这把-key-的用途" tabindex="-1">2. 记住这把 Key 的用途 <a class="header-anchor" href="#_2-记住这把-key-的用途" aria-label="Permalink to &quot;2. 记住这把 Key 的用途&quot;">​</a></h3><p>同一个 Key 可以同时给 Claude Desktop 和 Codex 使用，额度统一走熊猫算力后台管理。</p><p><img src="'+n+'" alt="熊猫算力后台令牌管理页"></p><hr><h2 id="step-03-找到-codex-配置目录" tabindex="-1">Step 03：找到 <code>.codex</code> 配置目录 <a class="header-anchor" href="#step-03-找到-codex-配置目录" aria-label="Permalink to &quot;Step 03：找到 `.codex` 配置目录&quot;">​</a></h2><h3 id="_1-打开配置目录" tabindex="-1">1. 打开配置目录 <a class="header-anchor" href="#_1-打开配置目录" aria-label="Permalink to &quot;1. 打开配置目录&quot;">​</a></h3><p>Codex 会读取用户目录下的 <code>.codex</code> 文件夹。</p><table tabindex="0"><thead><tr><th>平台</th><th>路径</th></tr></thead><tbody><tr><td>Windows</td><td><code>%USERPROFILE%\\.codex</code></td></tr><tr><td>macOS</td><td><code>~/.codex</code></td></tr></tbody></table><h3 id="_2-确认两个文件" tabindex="-1">2. 确认两个文件 <a class="header-anchor" href="#_2-确认两个文件" aria-label="Permalink to &quot;2. 确认两个文件&quot;">​</a></h3><p>目录里主要只需要处理这两个文件：</p><ul><li><code>auth.json</code></li><li><code>config.toml</code></li></ul><p><img src="'+d+'" alt=".codex 目录里的文件结构"></p><div class="tip custom-block"><p class="custom-block-title">找不到目录</p><p><code>.codex</code> 是点号开头的隐藏目录。Windows 需要开启“显示隐藏的项目”，macOS 需要显示隐藏文件。</p></div><hr><h2 id="step-04-编辑-auth-json" tabindex="-1">Step 04：编辑 <code>auth.json</code> <a class="header-anchor" href="#step-04-编辑-auth-json" aria-label="Permalink to &quot;Step 04：编辑 `auth.json`&quot;">​</a></h2><h3 id="_1-写入-api-key" tabindex="-1">1. 写入 API Key <a class="header-anchor" href="#_1-写入-api-key" aria-label="Permalink to &quot;1. 写入 API Key&quot;">​</a></h3><p>在 <code>.codex</code> 目录下新建或编辑 <code>auth.json</code>，内容如下：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;OPENAI_API_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-你的熊猫算力Key&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><img src="'+l+`" alt="auth.json 在记事本里打开,Key 部分打码"></p><h3 id="_2-常见错误" tabindex="-1">2. 常见错误 <a class="header-anchor" href="#_2-常见错误" aria-label="Permalink to &quot;2. 常见错误&quot;">​</a></h3><ul><li>Key 不是 OpenAI 官方 Key，而是熊猫算力后台生成的 <code>sk-</code> 开头密钥</li><li>Key 前后不要多空格、换行</li><li>JSON 必须使用英文半角引号</li></ul><hr><h2 id="step-05-编辑-config-toml" tabindex="-1">Step 05：编辑 <code>config.toml</code> <a class="header-anchor" href="#step-05-编辑-config-toml" aria-label="Permalink to &quot;Step 05：编辑 \`config.toml\`&quot;">​</a></h2><h3 id="_1-写入最小可用配置" tabindex="-1">1. 写入最小可用配置 <a class="header-anchor" href="#_1-写入最小可用配置" aria-label="Permalink to &quot;1. 写入最小可用配置&quot;">​</a></h3><p>把下面内容粘贴到 <code>config.toml</code>：</p><div class="language-toml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ---------- 全局核心(必须)----------</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_provider = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Pandaapi&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gpt-5.3-codex&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">preferred_auth_method = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;apikey&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ---------- 第三方中转(必须)----------</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">model_providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Pandaapi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Pandaapi&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;openai&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://b.pandatoken.net/v1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wire_api = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;responses&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">requires_openai_auth = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ---------- 至少一个信任目录(必须)----------</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">projects</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&#39;c:\\users\\你的用户名\\工作目录&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">trust_level = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;trusted&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p><img src="`+r+'" alt="config.toml 在记事本里打开,显示完整配置"></p><h3 id="_2-配置含义" tabindex="-1">2. 配置含义 <a class="header-anchor" href="#_2-配置含义" aria-label="Permalink to &quot;2. 配置含义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>作用</th></tr></thead><tbody><tr><td><code>model_provider</code></td><td>指定使用哪个 provider，必须和下面的 section 名一致</td></tr><tr><td><code>model</code></td><td>默认模型名，例如 <code>gpt-5.3-codex</code></td></tr><tr><td><code>preferred_auth_method</code></td><td>设为 <code>apikey</code>，让 Codex 读取本地 Key</td></tr><tr><td><code>base_url</code></td><td>熊猫算力的 OpenAI 兼容入口，末尾 <code>/v1</code> 不能少</td></tr><tr><td><code>wire_api</code></td><td>Codex 桌面版必须使用 <code>responses</code></td></tr><tr><td><code>trust_level</code></td><td>至少要有一个信任目录，否则 Codex 不会执行目录内操作</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">格式提醒</p><p><code>config.toml</code> 里字符串要用英文双引号，布尔值写 <code>true / false</code>，section 标记前不能缩进。</p></div><hr><h2 id="step-06-重启并验证" tabindex="-1">Step 06：重启并验证 <a class="header-anchor" href="#step-06-重启并验证" aria-label="Permalink to &quot;Step 06：重启并验证&quot;">​</a></h2><h3 id="_1-完全退出-codex" tabindex="-1">1. 完全退出 Codex <a class="header-anchor" href="#_1-完全退出-codex" aria-label="Permalink to &quot;1. 完全退出 Codex&quot;">​</a></h3><p>Windows 右下角系统托盘里把 Codex 退干净，macOS 用 <code>⌘+Q</code> 完全退出。</p><h3 id="_2-重新打开并测试" tabindex="-1">2. 重新打开并测试 <a class="header-anchor" href="#_2-重新打开并测试" aria-label="Permalink to &quot;2. 重新打开并测试&quot;">​</a></h3><p>启动后新建一个对话，发一句“你好”。如果右下角显示 <code>Pandaapi</code>，并且能正常返回回复，就说明接入成功。</p><p><img src="'+p+'" alt="Codex 主界面成功对话,右下角显示 Pandaapi"></p><h3 id="_3-成功标志" tabindex="-1">3. 成功标志 <a class="header-anchor" href="#_3-成功标志" aria-label="Permalink to &quot;3. 成功标志&quot;">​</a></h3><ol><li>输入框右下角出现 <code>Pandaapi</code></li><li>对话可以正常返回</li><li>熊猫算力后台能看到调用日志</li></ol><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="_1-还是走官方接口" tabindex="-1">1. 还是走官方接口 <a class="header-anchor" href="#_1-还是走官方接口" aria-label="Permalink to &quot;1. 还是走官方接口&quot;">​</a></h3><p>先完全退出 Codex，再重新打开。然后检查 <code>config.toml</code> 里的 <code>model_provider = &quot;Pandaapi&quot;</code> 和 <code>[model_providers.Pandaapi]</code> 是否完全一致。</p><h3 id="_2-401-unauthorized" tabindex="-1">2. 401 Unauthorized <a class="header-anchor" href="#_2-401-unauthorized" aria-label="Permalink to &quot;2. 401 Unauthorized&quot;">​</a></h3><p>检查 <code>auth.json</code> 里的 Key 是否复制正确，前后有没有空格，<code>preferred_auth_method</code> 是否写成了 <code>apikey</code>.</p><h3 id="_3-model-not-found" tabindex="-1">3. model not found <a class="header-anchor" href="#_3-model-not-found" aria-label="Permalink to &quot;3. model not found&quot;">​</a></h3><p>检查模型名是否写错，例如 <code>gpt-5.3-codex</code> 不要写成 <code>gpt5.3-codex</code>，同时确认熊猫算力后台已经开通这个模型。</p><h3 id="_4-connection-refused-超时" tabindex="-1">4. Connection refused / 超时 <a class="header-anchor" href="#_4-connection-refused-超时" aria-label="Permalink to &quot;4. Connection refused / 超时&quot;">​</a></h3><p>确认 <code>base_url</code> 是 <code>https://b.pandatoken.net/v1</code>，并检查本地代理是否干扰了请求。</p><h3 id="_5-toml-parse-error" tabindex="-1">5. TOML parse error <a class="header-anchor" href="#_5-toml-parse-error" aria-label="Permalink to &quot;5. TOML parse error&quot;">​</a></h3><p>最常见原因是：</p><ul><li>字符串没加英文引号</li><li>布尔值被写成了字符串</li><li>section 前面有缩进</li><li>文件被错误地保存成了带 BOM 的编码</li></ul><hr><p>配置完成后，Codex 就会通过熊猫算力网关运行。后续如果你还想把 Claude Desktop 也接进去，可以直接用同一把 Key。</p>',73)])])}const g=e(c,[["render",h]]);export{E as __pageData,g as default};
